statement:
A network of `n` servers, labelled `0` to `n - 1`, forms a tree with weighted links: each `edges[i] = [a_i, b_i, weight_i]` joins servers `a_i` and `b_i` in both directions with length `weight_i`. The distance between two servers is the total length of the unique path between them. You also get an integer `signalSpeed`.

A pair of servers `a` and `b` counts as connectable through server `c` when all of these hold:

- `a < b`, and neither `a` nor `b` is `c`;
- the distances from `c` to `a` and from `c` to `b` are both multiples of `signalSpeed`;
- the path from `c` to `a` and the path from `c` to `b` have no edge in common.

Return an array `count` of length `n` in which `count[i]` is how many pairs are connectable through server `i`. The edges are guaranteed to form a valid tree.

validator:
function validate([edges, signalSpeed]) {
  const n = edges.length + 1;
  if (n < 2 || n > 1000) return 'The tree needs 2 to 1000 servers (1 to 999 edges).';
  if (!Number.isInteger(signalSpeed) || signalSpeed < 1 || signalSpeed > 1e6) return 'signalSpeed is between 1 and 10^6.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is [a, b, weight].';
    const [a, b, weight] = edge;
    if (![a, b].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Edge endpoints must be servers 0 to n - 1, where n = edges.length + 1.';
    if (!Number.isInteger(weight) || weight < 1 || weight > 1e6) return 'Each weight is between 1 and 10^6.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'The edges must form a tree (no cycles or repeated edges).';
    root[ra] = rb;
  }
  return null;
}

