function countPairsOfConnectableServers(edges, signalSpeed) {
  const n = edges.length + 1;
  const neighbours = Array.from({ length: n }, () => []);
  const weights = Array.from({ length: n }, () => []);
  for (const [a, b, weight] of edges) {
    neighbours[a].push(b);
    weights[a].push(weight);
    neighbours[b].push(a);
    weights[b].push(weight);
  }

  const countDivisible = (start, parent, distance) => {
    let found = 0;
    const stack = [start];
    const from = [parent];
    const dist = [distance];
    while (stack.length > 0) {
      const node = stack.pop();
      const back = from.pop();
      const length = dist.pop();
      if (length % signalSpeed === 0) found++;
      for (let k = 0; k < neighbours[node].length; k++) {
        if (neighbours[node][k] === back) continue;
        stack.push(neighbours[node][k]);
        from.push(node);
        dist.push(length + weights[node][k]);
      }
    }
    return found;
  };

  const count = new Array(n).fill(0);
  for (let c = 0; c < n; c++) {
    let before = 0;
    for (let k = 0; k < neighbours[c].length; k++) {
      const reachable = countDivisible(neighbours[c][k], c, weights[c][k]);
      count[c] += before * reachable;
      before += reachable;
    }
  }
  return count;
}

