function countPairsOfConnectableServers(edges, signalSpeed) {
  const n = edges.length + 1;
  const result = [];
  for (let c = 0; c < n; c++) {
    // Breadth-first search from c records each server's distance and the edge it was reached by.
    const dist = Array(n).fill(-1), via = Array(n).fill(-1), parent = Array(n).fill(-1);
    dist[c] = 0;
    const queue = [c];
    for (let q = 0; q < queue.length; q++) {
      const u = queue[q];
      edges.forEach(([a, b, w], id) => {
        const v = a === u ? b : b === u ? a : -1;
        if (v >= 0 && dist[v] < 0) { dist[v] = dist[u] + w; via[v] = id; parent[v] = u; queue.push(v); }
      });
    }
    const pathEdges = (v) => { const ids = new Set(); while (v !== c) { ids.add(via[v]); v = parent[v]; } return ids; };
    let total = 0;
    for (let a = 0; a < n; a++) {
      for (let b = a + 1; b < n; b++) {
        if (a === c || b === c || dist[a] % signalSpeed !== 0 || dist[b] % signalSpeed !== 0) continue;
        const toA = pathEdges(a);
        if ([...pathEdges(b)].every(id => !toA.has(id))) total++;
      }
    }
    result.push(total);
  }
  return result;
}

