function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? pick(450, 550) : pick(2, 9);
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(0, i); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  const chain = rand() < 0.3;
  const maxWeight = size === 'large' ? (rand() < 0.5 ? 1e6 : 6) : pick(1, 6);
  for (let i = 1; i < n; i++) {
    const parent = chain ? i - 1 : pick(Math.max(0, i - 1 - Math.floor(rand() * i)), i - 1);
    const edge = [label[parent], label[i], pick(1, maxWeight)];
    if (rand() < 0.5) [edge[0], edge[1]] = [edge[1], edge[0]];
    edges.push(edge);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const signalSpeed = size === 'large' ? [1, 2, 3, 7, 1e6][pick(0, 4)] : pick(1, 4);
  return [edges, signalSpeed];
}
